package org.dromara.warehouse.outbound.service.impl;
import org.dromara.common.core.exception.ServiceException;import org.dromara.property.api.ProjectReferenceService;import org.dromara.warehouse.inventory.service.InventoryMutationService;import org.dromara.warehouse.location.mapper.WarehouseLocationMapper;import org.dromara.warehouse.material.mapper.MaterialMapper;import org.dromara.warehouse.outbound.domain.OutboundOrder;import org.dromara.warehouse.outbound.mapper.*;import org.dromara.warehouse.security.WarehouseAccessService;import org.dromara.warehouse.unit.mapper.UnitMapper;import org.dromara.warehouse.warehouse.domain.Warehouse;import org.dromara.warehouse.zone.mapper.WarehouseZoneMapper;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.transaction.annotation.Transactional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class OutboundOrderServiceImplTest {
 @Mock OutboundOrderMapper orderMapper;@Mock OutboundOrderItemMapper itemMapper;@Mock WarehouseAccessService accessService;@Mock WarehouseLocationMapper locationMapper;@Mock WarehouseZoneMapper zoneMapper;@Mock MaterialMapper materialMapper;@Mock UnitMapper unitMapper;@Mock InventoryMutationService mutationService;@Mock ProjectReferenceService projectReferenceService;@InjectMocks OutboundOrderServiceImpl service;
 @Test void repeatedCompleteFailsBeforeInventory(){OutboundOrder o=order("COMPLETED");when(orderMapper.selectForUpdate(1L)).thenReturn(o);when(accessService.requireEnabledWarehouse(2L)).thenReturn(new Warehouse());assertThrows(ServiceException.class,()->service.complete(1L));verifyNoInteractions(mutationService);}
 @Test void completedCannotCancel(){OutboundOrder o=order("COMPLETED");when(orderMapper.selectForUpdate(1L)).thenReturn(o);assertThrows(ServiceException.class,()->service.cancel(1L));verify(orderMapper,never()).cancelCas(anyLong());}
 @Test void detailIdorRejectedBeforeJoinedQuery(){OutboundOrder o=order("DRAFT");when(orderMapper.selectById(1L)).thenReturn(o);doThrow(new ServiceException("denied")).when(accessService).requireWarehouse(2L);assertThrows(ServiceException.class,()->service.queryById(1L));verify(orderMapper,never()).selectOutboundById(anyLong());}
 @Test void completeHasTransactionBoundary()throws Exception{assertNotNull(OutboundOrderServiceImpl.class.getMethod("complete",Long.class).getAnnotation(Transactional.class));}
 private OutboundOrder order(String status){OutboundOrder o=new OutboundOrder();o.setId(1L);o.setWarehouseId(2L);o.setStatus(status);return o;}
}
